def day_of_programmer(year: int) -> str:
    if year == 1918:
        return f'26.09.{year}'
    elif year < 1918:
        is_leap = (year % 4 == 0)
    else:
        is_leap = (year % 400 == 0) or (year % 4 == 0 and year % 100 != 0)
    day = 12 if is_leap else 13
    return f'{day:02d}.09.{year}'
